1	/**
2	 * FinancialBIService — inteligência financeira da empresa (Slice 3, R13-R16).
3	 *
4	 * Implementa 4 queries derivadas de BI sobre escrow_transactions + jobs + applications.
5	 * Nenhuma view criada (decisão do architect: views não propagam RLS com segurança — spec Slice 3).
6	 *
7	 * BI-2: Gasto e horas por freela (real: checkout-checkin; fallback: jobs.estimated_hours).
8	 * BI-3: Ratio custo/hora + custo-%-faturamento (oculto se mês sem faturamento informado).
9	 * BI-4: Custo de no-show — heurística v1, ROTULADO COMO ESTIMATIVA.
10	 * BI-5: Flag de concentração de horas/dias por freela (risco de vínculo trabalhista).
11	 *
12	 * Contratos de dados (spec Slice 3):
13	 *  - Gasto = escrow_transactions WHERE status IN ('released','captured').
14	 *  - Carimbo: COALESCE(captured_at, released_at, created_at) — filtrar o mês por este.
15	 *  - Empresa da linha: company_wallet_id → wallets.user_id = companyId.
16	 *  - Freela: worker_wallet_id → wallets.user_id | application_id → applications.worker_id.
17	 *
18	 * Padrões do projeto:
19	 *  - supabase.from direto (Art. 5 — sem React Query).
20	 *  - Tipos à mão em types/index.ts (Art. 2).
21	 *  - Imports relativos (sem alias @/).
22	 *  - logError (nunca console.log).
23	 */
24	
25	import { supabase } from '../lib/supabase';
26	import { logError } from '../lib/logger';
27	import type {
28	  AccumulatedSpend,
29	  SpendByWorker,
30	  CostRatio,
31	  NoShowCost,
32	  ConcentrationFlag,
33	} from '../types';
34	
35	// ---------------------------------------------------------------------------
36	// Constantes de produto (BI-5 — limiar de concentração)
37	// Calibrar aqui sem migration.
38	// ---------------------------------------------------------------------------
39	
40	/** Horas totais no período que sinalizam risco de vínculo. */
41	const CONCENTRATION_HOURS_THRESHOLD = 150;
42	
43	/** Dias distintos no período que, combinados com as horas, sinalizam risco de vínculo. */
44	const CONCENTRATION_DAYS_THRESHOLD = 20;
45	
46	// ---------------------------------------------------------------------------
47	// Helpers de período
48	// ---------------------------------------------------------------------------
49	
50	export interface BIPeriod {
51	  /** Primeiro dia do mês (inclusive), ISO date string YYYY-MM-DD. */
52	  start: string;
53	  /** Primeiro dia do mês seguinte (exclusive), ISO date string YYYY-MM-DD. */
54	  end: string;
55	}
56	
57	/** Retorna o período do mês corrente. */
58	export function currentMonthPeriod(now: Date = new Date()): BIPeriod {
59	  const y = now.getFullYear();
60	  const m = String(now.getMonth() + 1).padStart(2, '0');
61	  const start = `${y}-${m}-01`;
62	  const next = new Date(y, now.getMonth() + 1, 1);
63	  const ny = next.getFullYear();
64	  const nm = String(next.getMonth() + 1).padStart(2, '0');
65	  const end = `${ny}-${nm}-01`;
66	  return { start, end };
67	}
68	
69	/** Retorna um período customizado a partir de strings ISO date. */
70	export function customPeriod(start: string, end: string): BIPeriod {
71	  return { start, end };
72	}
73	
74	// ---------------------------------------------------------------------------
75	// Tipos internos de linha bruta de escrow
76	// ---------------------------------------------------------------------------
77	
78	interface EscrowRow {
79	  amount: number;
80	  captured_at: string | null;
81	  released_at: string | null;
82	  created_at: string;
83	  application_id: string | null;
84	  worker_wallet_id: string | null;
85	  job_id: string | null;
86	}
87	
