289	      // 4. Agregar por worker
290	      interface WorkerAgg {
291	        totalAmount: number;
292	        totalHours: number;
293	        realHoursCount: number;
294	        estimatedHoursCount: number;
295	        shiftsCount: number;
296	      }
297	
298	      const agg = new Map<string, WorkerAgg>();
299	
300	      for (const row of inPeriod) {
301	        const app = appMap.get(row.application_id as string);
302	        if (!app) continue;
303	
304	        const workerId = app.worker_id;
305	        if (!agg.has(workerId)) {
306	          agg.set(workerId, {
307	            totalAmount: 0,
308	            totalHours: 0,
309	            realHoursCount: 0,
310	            estimatedHoursCount: 0,
311	            shiftsCount: 0,
312	          });
313	        }
314	        const entry = agg.get(workerId)!;
315	        entry.totalAmount += Number(row.amount ?? 0);
316	        entry.shiftsCount += 1;
317	
318	        // Horas: real se houver check-in/out; fallback estimated_hours
319	        if (app.worker_checkin_at && app.worker_checkout_at) {
320	          const hours =
321	            (new Date(app.worker_checkout_at).getTime() -
322	              new Date(app.worker_checkin_at).getTime()) /
323	            3_600_000;
324	          entry.totalHours += hours;
325	          entry.realHoursCount += 1;
326	        } else {
327	          const job = row.job_id ? jobMap.get(row.job_id) : undefined;
328	          const estimated = job?.estimated_hours ?? 0;
329	          entry.totalHours += estimated;
330	          entry.estimatedHoursCount += 1;
331	        }
332	      }
333	
334	      // 5. Montar resultado
335	      const result: SpendByWorker[] = [];
336	      for (const [workerId, data] of agg.entries()) {
337	        const worker = workerMap.get(workerId);
338	        let hoursSource: SpendByWorker['hoursSource'] = 'estimated';
339	        if (data.realHoursCount > 0 && data.estimatedHoursCount === 0) {
340	          hoursSource = 'real';
341	        } else if (data.realHoursCount > 0 && data.estimatedHoursCount > 0) {
342	          hoursSource = 'mixed';
343	        }
344	
345	        result.push({
346	          workerId,
347	          workerName: worker?.full_name ?? 'Worker',
348	          workerAvatarUrl: worker?.avatar_url ?? worker?.photo_url ?? null,
349	          totalAmount: data.totalAmount,
350	          totalHours: data.totalHours,
351	          hoursSource,
352	          shiftsCount: data.shiftsCount,
353	        });
354	      }
355	
356	      // Ordenar por gasto descendente
357	      result.sort((a, b) => b.totalAmount - a.totalAmount);
358	      return result;
359	    } catch (err) {
360	      logError('financialBI.getSpendByWorker', err);
