426	  // -------------------------------------------------------------------------
427	  // BI-4: Custo de no-show (heurística v1)
428	  // -------------------------------------------------------------------------
429	
430	  /**
431	   * Estima o custo de no-show no período (BI-4 — HEURÍSTICA V1, ROTULADO COMO ESTIMATIVA).
432	   *
433	   * Heurística: application com invitation_response='accepted' (ou status='hired') cujo
434	   * turno já passou (jobs.start_date < now) E sem worker_checkout_at E sem conclusão.
435	   *
436	   * No postpago, o no-show antes da captura resulta em hold liberado (custo real = 0).
437	   * O estimatedAmount expõe o custo de oportunidade (valor do turno que não aconteceu).
438	   *
439	   * GAP sinalizado: sem coluna explícita no_show na v1. Se o piloto exigir precisão,
440	   * escalar para architect → marcador explícito de no-show em applications (migration menor).
441	   */
442	  async getNoShowCost(companyId: string, period: BIPeriod): Promise<NoShowCost> {
443	    const empty: NoShowCost = { estimatedCount: 0, estimatedAmount: 0, isEstimate: true };
444	
445	    try {
446	      // Buscar jobs da empresa no período
447	      const { data: jobs, error: jobsErr } = await supabase
448	        .from('jobs')
449	        .select('id, start_date, budget')
450	        .eq('company_id', companyId)
451	        .gte('start_date', period.start)
452	        .lt('start_date', period.end);
453	
454	      if (jobsErr) {
455	        logError('financialBI.getNoShowCost.jobs', jobsErr);
456	        return empty;
457	      }
458	
459	      if (!jobs || jobs.length === 0) return empty;
460	
461	      const now = new Date();
462	      const pastJobIds = (jobs as Array<{ id: string; start_date: string; budget: number }>)
463	        .filter((j) => new Date(j.start_date) < now)
464	        .map((j) => j.id);
465	
466	      if (pastJobIds.length === 0) return empty;
467	
468	      const jobBudgetMap = new Map<string, number>(
469	        (jobs as Array<{ id: string; budget: number }>).map((j) => [j.id, Number(j.budget ?? 0)]),
470	      );
471	
472	      // Buscar applications de turnos passados da empresa que podem ser no-show
473	      const { data: apps, error: appsErr } = await supabase
474	        .from('applications')
475	        .select('id, job_id, status, worker_checkout_at, invitation_response')
476	        .in('job_id', pastJobIds)
477	        .in('status', ['hired', 'in_progress'])
478	        .is('worker_checkout_at', null);
479	
480	      if (appsErr) {
481	        logError('financialBI.getNoShowCost.apps', appsErr);
482	        return empty;
483	      }
484	
485	      // Filtrar: convite aceito (invitation_response='accepted' ou status='hired') sem checkout
486	      const noShows = ((apps ?? []) as Pick<
487	        ApplicationRow,
488	        'id' | 'job_id' | 'status' | 'worker_checkout_at' | 'invitation_response'
489	      >[]).filter(
490	        (a) =>
491	          a.invitation_response === 'accepted' ||
492	          a.status === 'hired' ||
493	          a.status === 'in_progress',
494	      );
495	
496	      let estimatedAmount = 0;
497	      for (const ns of noShows) {
498	        estimatedAmount += jobBudgetMap.get(ns.job_id) ?? 0;
499	      }
500	
501	      return {
502	        estimatedCount: noShows.length,
503	        estimatedAmount,
504	        isEstimate: true,
505	      };
506	    } catch (err) {
507	      logError('financialBI.getNoShowCost', err);
508	      return empty;
509	    }
510	  },
