616	  // -------------------------------------------------------------------------
617	  // Conveniência: todos os BI de uma vez (para o hook useFinancialBI)
618	  // -------------------------------------------------------------------------
619	
620	  /**
621	   * Computa todos os indicadores do período de uma vez.
622	   * Reutiliza getSpendByWorker entre BI-2, BI-3 e BI-5 para evitar queries duplas.
623	   *
624	   * @param companyId UUID da empresa.
625	   * @param period    Período (usar currentMonthPeriod() ou customPeriod()).
626	   */
627	  async getAllBI(
628	    companyId: string,
629	    period: BIPeriod,
630	  ): Promise<{
631	    accumulatedSpend: AccumulatedSpend;
632	    spendByWorker: SpendByWorker[];
633	    costRatio: CostRatio;
634	    noShowCost: NoShowCost;
635	    concentrationFlags: ConcentrationFlag[];
636	  }> {
637	    // Computar em paralelo onde não há dependência
638	    const [accumulatedSpend, spendByWorker, noShowCost] = await Promise.all([
639	      FinancialBIService.getAccumulatedSpend(companyId, period),
640	      FinancialBIService.getSpendByWorker(companyId, period),
641	      FinancialBIService.getNoShowCost(companyId, period),
642	    ]);
643	
644	    // BI-3 e BI-5 dependem de spendByWorker
645	    const [costRatio, concentrationFlags] = await Promise.all([
646	      FinancialBIService.getCostRatio(
647	        spendByWorker,
648	        accumulatedSpend.totalAmount,
649	        companyId,
650	        period.start,
651	      ),
652	      FinancialBIService.getConcentrationFlags(companyId, period, spendByWorker),
653	    ]);
654	
655	    return { accumulatedSpend, spendByWorker, costRatio, noShowCost, concentrationFlags };
656	  },
657	};
